import {pad,norm,uid,categoryFor,preview,createContent,issue,addCategory,setCategoryActive,renameCategory,editContent,cancelClass,csvCell} from './engine.js';
import {transact,read,reset,onUpdate} from './store.js';
const $=s=>document.querySelector(s),h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',plus:'M12 5v14 M5 12h14',book:'M4 4h12a4 4 0 0 1 4 4v13H8a4 4 0 0 1-4-4Zm0 13a4 4 0 0 1 4-4h12',grid:'M3 3h7v7H3Z M14 3h7v7h-7Z M3 14h7v7H3Z M14 14h7v7h-7Z',list:'M8 5h13 M8 12h13 M8 19h13 M3 5h1 M3 12h1 M3 19h1',arrow:'M5 12h14 M14 6l6 6-6 6',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',check:'m5 12 4 4L20 5',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',bolt:'m13 2-9 12h7l-1 8 10-12h-7Z'};
const ico=n=>`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.grid}"/></svg>`;
const modes={OF:'Offline',ON:'Online trực tiếp',EL:'E-learning',BL:'Blended'};
let s,view='home',role='admin',search='',ownerFilter='',modeFilter='',categoryFilter='active',requestId=uid(),lastIssue=null;
const dialog=$('#dialog');let modalAction=null;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function pill(t,kind=''){return `<span class="pill ${kind}">${h(t)}</span>`}
function btn(label,action,kind='',id=''){return `<button class="button ${kind}" data-action="${action}" data-id="${h(id)}">${label}</button>`}
const ownerOpts=(selected='')=>s.owners.map(o=>`<option value="${o.code}" ${o.code===selected?'selected':''}>${h(o.name)} · ${o.code}</option>`).join('');
const catOpts=(selected='')=>s.categories.filter(c=>c.active).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${h(c.name)} · ${c.code}</option>`).join('');
function header(title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">WORKSPACE / ${view==='home'?'OVERVIEW':'CLASS MANAGEMENT'}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function render(){
 const nav=[['home','home','Tổng quan'],['issue','plus','Mở lớp & cấp mã'],['contents','book','Nội dung lớp'],['cats','grid','Danh mục CAT'],['registry','list','Sổ mã lớp']];
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#home"><img src="./icon.svg" alt=""><div>Classcode<span>IPA GROUP · LEARNING</span></div></a><div class="workspace-label">KHÔNG GIAN LÀM VIỆC</div><nav aria-label="Điều hướng">${nav.map(([id,icon,label])=>`<a href="#${id}" class="nav-link ${id===view?'active':''}" ${id===view?'aria-current="page"':''}>${ico(icon)}<span>${label}</span>${id===view?'<i></i>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="prototype"><span class="dot"></span> PROTOTYPE V1.0</div><p>Dữ liệu minh họa.<br>Lưu riêng trên trình duyệt này.</p><button class="text-button" data-action="help">Cách trình bày demo ${ico('arrow')}</button></div><div class="profile"><div class="avatar">LD</div><div>L&D Workspace<small>IPA Group</small></div></div></aside>
 <div class="workspace"><header class="topbar"><div class="breadcrumb">Learning operations <span>/</span> Classcode</div><div class="top-right">${pill('Demo cục bộ','soft')}<label class="role-label">Vai trò mô phỏng<select id="role" aria-label="Vai trò mô phỏng"><option value="admin" ${role==='admin'?'selected':''}>Quản trị danh mục</option><option value="ld" ${role==='ld'?'selected':''}>L&D contact point</option></select></label></div></header><main id="main" tabindex="-1">${({home:home,issue:issuePage,contents:contentsPage,cats:catsPage,registry:registryPage}[view])()}</main><footer>CLASSCODE <span>Đơn vị sở hữu → Nhóm chủ đề → Lớp học</span><button data-action="help" class="text-button">Phạm vi prototype ${ico('info')}</button></footer></div>`;
 if(view==='issue')updatePreview();
}
function home(){return `${header('Mỗi lớp học, một mã rõ ràng.','Từ nội dung đến lần mở lớp. Một quy trình thống nhất cho toàn tập đoàn.',btn(`${ico('plus')} Mở lớp mới`,'navigate','primary','issue'))}
 <div class="hero"><div class="hero-copy"><span class="eyebrow">THƯ MỤC 3 TẦNG · QUY TẮC 6 TRƯỜNG</span><h2>Chọn thông tin.<br>Để hệ thống cấp mã.</h2><p>Liên kết đơn vị sở hữu, nhóm chủ đề và từng lần mở lớp. Giữ lịch sử ngay cả khi danh mục thay đổi.</p><div class="hero-actions">${btn('Thử cấp mã '+ico('arrow'),'navigate','primary','issue')}${btn('Xem quy tắc','rules','ghost')}</div></div><div class="code-story"><div class="code-story-label"><span class="dot"></span> CẤU TRÚC NAMECODE</div><div class="large-code"><span>IPAG</span><b>_</b><span>SKL</span><b>_</b><span>0002</span><br><span>OF</span><b>_</b><span>2026</span><b>_</b><span>001</span></div><div class="code-labels"><span>OWN · Chủ sở hữu</span><span>CAT · Nhóm chủ đề</span><span>KKKK · Nội dung</span><span>HT · Hình thức</span><span>YYYY · Năm mở</span><span>DDD · Lần đăng ký</span></div><div class="code-story-foot">Một nội dung. Nhiều lần mở. Không thêm tầng thư mục.</div></div></div>
 <div class="stats">${[['Mã lớp đã cấp',s.classes.length,'list','Kể cả lớp hủy để giữ lịch sử'],['Nội dung lớp',s.contents.length,'book','Dùng lại KKKK cho lần mở mới'],['CAT đang hoạt động',s.categories.filter(c=>c.active).length,'grid','Danh mục cập nhật ngay trong app']].map(([label,value,icon,note])=>`<div class="stat"><div><span>${label}</span>${ico(icon)}</div><strong>${value}</strong><small>${note}</small></div>`).join('')}</div>
 <div class="two-col"><section class="panel"><div class="section-head"><h3>Mã lớp gần đây</h3><a href="#registry">Xem tất cả ${ico('arrow')}</a></div>${s.classes.slice(0,4).map(r=>{const c=s.contents.find(c=>c.id===r.contentId);return `<button class="recent-row" data-action="detail" data-id="${r.id}"><div class="mini-icon">${ico('book')}</div><div><strong>${h(c.title)}</strong><code>${h(r.code)}</code></div>${pill(r.mode)}${ico('arrow')}</button>`}).join('')}</section><section class="panel demo-card"><span class="eyebrow">THỬ NGHIỆM QUY TRÌNH</span><h3>Hai yêu cầu. Hai mã riêng.</h3><p>Mô phỏng hai người cùng cấp mã cho một nội dung và một năm. Sau đó gửi lại yêu cầu đầu để kiểm tra chống cấp lặp.</p><div class="people"><span class="avatar">A</span><span class="avatar alt">B</span><span>Cùng trình duyệt · dữ liệu dùng chung</span></div>${btn('Chạy mô phỏng '+ico('bolt'),'simulation','secondary')}<small>Mô phỏng giao dịch cục bộ; không phải cấp mã giữa nhiều máy.</small></section></div>`}
function issuePage(){return `${header('Mở lớp & cấp mã','Chọn nội dung đã có. Hệ thống tự lấy đơn vị sở hữu và CAT từ sổ nội dung.',btn(ico('plus')+' Nội dung mới','new-content','secondary'))}<div class="issue-layout"><section class="panel form-panel"><div class="section-head"><h3>Thông tin lớp học</h3>${pill('01 / NHẬP THÔNG TIN','soft')}</div><form id="issue-form"><label>Nội dung lớp <span class="required">*</span><select name="contentId" required><option value="">Chọn nội dung trong sổ…</option>${s.contents.map(c=>`<option value="${c.id}" ${!categoryFor(s,c).active?'disabled':''}>${h(c.title)} · ${pad(c.number,4)}${categoryFor(s,c).active?'':' · CAT đã ngừng'}</option>`).join('')}</select></label><div id="content-context" class="context-box">${ico('info')} Đơn vị sở hữu, CAT và KKKK sẽ được lấy tự động.</div><div class="form-grid"><label>Hình thức học <span class="required">*</span><select name="mode" required><option value="">Chọn hình thức…</option>${Object.entries(modes).map(([k,v])=>`<option value="${k}">${v} · ${k}</option>`).join('')}</select></label><label>Ngày mở lớp <span class="required">*</span><input name="date" type="date" min="1900-01-01" max="2199-12-31" required></label></div><label>Nhãn đợt / địa điểm <span class="optional">Tùy chọn</span><input name="label" maxlength="120" placeholder="Ví dụ: Đợt tháng 11 · Hà Nội"></label><p class="field-help">Online là lớp trực tuyến theo lịch. E-learning là tự học. Nhãn đợt giúp tra cứu và không nằm trong mã.</p><div id="duplicate-warning"></div><div class="form-bottom"><span>${ico('check')} Số được cấp khi lưu thành công</span><button class="button primary" type="submit">Cấp mã & lưu lớp ${ico('arrow')}</button></div><p class="error" id="issue-error" role="alert"></p></form></section><aside class="preview-panel"><div class="eyebrow">02 / XEM TRƯỚC</div><h3>Mã lớp của bạn</h3><div class="preview-code" id="code-preview">Chưa đủ thông tin</div><p class="field-help light">Xem trước chưa giữ số. Mã chính thức của bản demo được cấp khi bấm lưu.</p><div id="code-parts" class="parts"></div><div class="path"><span>ĐƯỜNG DẪN THƯ MỤC</span><p id="path-preview">Đơn vị sở hữu<br>↳ Nhóm chủ đề<br>　↳ [Mã] Tên lớp</p></div><div class="preview-note">${ico('info')} DDD tăng theo nội dung và năm, xuyên các hình thức. Mã đã hủy không được cấp lại.</div></aside></div>`}
function updatePreview(){const f=$('#issue-form');if(!f)return;const v=Object.fromEntries(new FormData(f)),c=s.contents.find(x=>x.id===v.contentId),p=preview(s,v.contentId,v.mode,v.date);$('#code-preview').textContent=p||'Chưa đủ thông tin';$('#content-context').innerHTML=c?`<div><small>ĐƠN VỊ SỞ HỮU</small><strong>${h(c.owner)}</strong></div><div><small>NHÓM CHỦ ĐỀ</small><strong>${h(categoryFor(s,c).code)}</strong></div><div><small>NỘI DUNG</small><strong>${pad(c.number,4)}</strong></div>`:`${ico('info')} Đơn vị sở hữu, CAT và KKKK sẽ được lấy tự động.`;$('#code-parts').innerHTML=p?p.split('_').map((v,i)=>`<div><span>${['Chủ sở hữu','Nhóm chủ đề','Nội dung lớp','Hình thức','Năm mở','Số đăng ký'][i]}</span><strong>${h(v)}</strong></div>`).join(''):'';$('#path-preview').innerHTML=c?`${h(c.owner)}<br>↳ ${h(categoryFor(s,c).name)}<br>　↳ ${h(p?'['+p+'] ':'')}${h(c.title)}`:'Đơn vị sở hữu<br>↳ Nhóm chủ đề<br>　↳ [Mã] Tên lớp';const matches=s.classes.filter(r=>r.contentId===v.contentId&&r.mode===v.mode&&r.date===v.date&&r.status==='active');$('#duplicate-warning').innerHTML=matches.length?`<div class="notice warning">Đã có ${matches.length} lớp cùng nội dung, hình thức và ngày. Kiểm tra Sổ mã trước khi cấp thêm.<label class="inline-check"><input type="checkbox" name="distinct" required> Tôi xác nhận đây là một lần mở lớp khác.</label></div>`:'';}
function contentsPage(){return `${header('Sổ nội dung lớp','Một nội dung có một KKKK ổn định. Dùng lại khi mở lớp ở năm hoặc hình thức khác.',btn(ico('plus')+' Đăng ký nội dung','new-content','primary'))}<section class="panel"><div class="toolbar"><div class="search">${ico('search')}<input id="search" aria-label="Tìm nội dung" placeholder="Tìm tên nội dung hoặc KKKK…" value="${h(search)}"></div><select id="owner-filter" aria-label="Lọc chủ sở hữu"><option value="">Tất cả đơn vị</option>${ownerOpts(ownerFilter)}</select><span class="muted">${s.contents.length} nội dung minh họa / đã tạo</span></div><div id="table-results">${contentRows()}</div></section>`}
function contentRows(){const rows=s.contents.filter(c=>(!ownerFilter||c.owner===ownerFilter)&&norm(c.title+' '+pad(c.number,4)).includes(norm(search)));return `<div class="table-wrap"><table><thead><tr><th>KKKK</th><th>Nội dung lớp</th><th>Đơn vị</th><th>CAT</th><th>Lần mở</th><th><span class="sr-only">Thao tác</span></th></tr></thead><tbody>${rows.map(c=>`<tr><td><code>${pad(c.number,4)}</code></td><td class="title-cell"><strong>${h(c.title)}</strong><small>${h(categoryFor(s,c).name)}${categoryFor(s,c).active?'':' · CAT đã ngừng'}</small></td><td>${pill(c.owner)}</td><td>${pill(categoryFor(s,c).code,categoryFor(s,c).active?'soft':'off')}</td><td>${s.classes.filter(r=>r.contentId===c.id).length}</td><td>${btn('Mở lớp','open-content','compact',c.id)} ${role==='admin'?btn('Sửa','edit-content','compact ghost',c.id):''}</td></tr>`).join('')}</tbody></table>${rows.length?'':empty('Không tìm thấy nội dung','Thử một từ khóa hoặc đơn vị khác.')}</div>`}
function catsPage(){return `${header('Danh mục nhóm chủ đề','Một cấp CAT, dùng chung quy tắc. Thay đổi danh mục mà không cần sửa mã nguồn.',role==='admin'?btn(ico('plus')+' Thêm CAT','new-cat','primary'):pill('Chế độ xem'))}<div class="notice">${ico('info')} Ngừng CAT sẽ chặn đăng ký và mở lớp mới trong nhóm. Lớp đã cấp mã vẫn được giữ để tra cứu.</div><section class="panel"><div class="toolbar"><div class="search">${ico('search')}<input id="search" aria-label="Tìm CAT" placeholder="Tìm nhóm chủ đề hoặc mã CAT…" value="${h(search)}"></div><select id="cat-filter" aria-label="Trạng thái CAT"><option value="active" ${categoryFilter==='active'?'selected':''}>Đang hoạt động</option><option value="all" ${categoryFilter==='all'?'selected':''}>Tất cả trạng thái</option><option value="inactive" ${categoryFilter==='inactive'?'selected':''}>Đã ngừng</option></select></div><div id="table-results">${catRows()}</div></section>`}
function catRows(){const rows=s.categories.filter(c=>(categoryFilter==='all'||c.active===(categoryFilter==='active'))&&norm(c.name+' '+c.code).includes(norm(search)));return `<div class="category-grid">${rows.map(c=>`<article class="category-card"><div class="section-head">${pill(c.code,c.active?'soft':'off')}<small>${s.contents.filter(x=>x.categoryId===c.id).length} nội dung</small></div><h3>${h(c.name)}</h3><p>${h(c.include)}</p><details><summary>Ranh giới phân loại</summary><p>${h(c.exclude||'Chưa bổ sung điều kiện loại trừ.')}</p></details><div class="category-actions"><span class="status ${c.active?'':'inactive'}">${c.active?'Đang hoạt động':'Đã ngừng'}</span>${role==='admin'?`<div>${btn('Sửa','edit-cat','compact ghost',c.id)}${btn(c.active?'Ngừng':'Kích hoạt','toggle-cat','compact ghost',c.id)}</div>`:''}</div></article>`).join('')||empty('Không có CAT phù hợp','Thay đổi bộ lọc hoặc thêm nhóm chủ đề mới.')}</div>`}
function registryPage(){return `${header('Sổ mã lớp','Tra cứu bằng tên, mã hiện hành hoặc mã cũ. Mỗi lớp giữ một ID bất biến.',btn(ico('download')+' Xuất CSV','export-csv','secondary'))}<section class="panel"><div class="toolbar"><div class="search wide">${ico('search')}<input id="search" aria-label="Tìm mã lớp" placeholder="Tìm tên lớp, mã hiện hành hoặc mã cũ…" value="${h(search)}"></div><select id="owner-filter" aria-label="Lọc đơn vị"><option value="">Tất cả đơn vị</option>${ownerOpts(ownerFilter)}</select><select id="mode-filter" aria-label="Lọc hình thức"><option value="">Tất cả hình thức</option>${Object.entries(modes).map(([k,v])=>`<option value="${k}" ${modeFilter===k?'selected':''}>${v}</option>`).join('')}</select></div><div id="table-results">${registryRows()}</div></section>`}
function registryRows(){const rows=s.classes.filter(r=>{const c=s.contents.find(x=>x.id===r.contentId);return (!ownerFilter||c.owner===ownerFilter)&&(!modeFilter||r.mode===modeFilter)&&norm(r.code+' '+r.aliases.join(' ')+' '+c.title+' '+r.label).includes(norm(search))});return `<div class="table-wrap"><table><thead><tr><th>Lớp học / Namecode</th><th>Ngày mở</th><th>Hình thức</th><th>Trạng thái</th><th></th></tr></thead><tbody>${rows.map(r=>{const c=s.contents.find(x=>x.id===r.contentId);return `<tr><td class="title-cell"><strong>${h(c.title)}</strong><code>${h(r.code)}</code><small>${h(r.label)}${r.aliases.length?' · '+r.aliases.length+' mã cũ':''}</small></td><td>${h(r.date.split('-').reverse().join('/'))}</td><td>${pill(r.mode)}</td><td>${pill(r.status==='active'?'Đã cấp':'Đã hủy',r.status==='active'?'soft':'off')}</td><td>${btn('Chi tiết '+ico('arrow'),'detail','compact ghost',r.id)}</td></tr>`}).join('')}</tbody></table>${rows.length?'':empty('Chưa tìm thấy lớp','Tìm theo tên, mã hiện hành hoặc một mã đã đổi trước đây.')}</div>`}
function empty(t,p){return `<div class="empty">${ico('search')}<h3>${t}</h3><p>${p}</p></div>`}
function showDialog(title,body,action=null){modalAction=action;dialog.innerHTML=`<div class="modal-head"><div><span class="eyebrow">CLASSCODE WORKSPACE</span><h2>${title}</h2></div><button class="icon-button" data-action="close" aria-label="Đóng">×</button></div><div class="modal-body">${body}</div>`;if(!dialog.open)dialog.showModal()}
function close(){dialog.close();modalAction=null}
function modalForm(html,save='Lưu thay đổi'){return `<form id="modal-form">${html}<p class="error" id="modal-error" role="alert"></p><div class="modal-footer">${btn('Đóng','close','ghost')}<button class="button primary" type="submit">${save} ${ico('check')}</button></div></form>`}
function contentDialog(id){const c=s.contents.find(x=>x.id===id);showDialog(c?'Chỉnh sửa nội dung lớp':'Đăng ký nội dung lớp',modalForm(`<div class="notice">${c?'Đổi nhánh sẽ cập nhật mã hiện hành của các lớp liên quan. ID và mã cũ vẫn được giữ.':'KKKK được hệ thống cấp. Tên lớp trong prototype là dữ liệu minh họa, không phải phân loại đã duyệt.'}</div><label>Tên nội dung lớp<input name="title" value="${h(c?.title||'')}" minlength="4" maxlength="160" required placeholder="Ví dụ: Thực hành kỹ năng thuyết trình"></label><div class="form-grid"><label>Đơn vị sở hữu<select name="owner" required>${ownerOpts(c?.owner||'IPAG')}</select></label><label>Nhóm chủ đề<select name="categoryId" required>${catOpts(c?.categoryId)}</select></label></div><div id="cat-guidance" class="context-box"></div>${c?'<label>Lý do thay đổi<input name="reason" required minlength="5" placeholder="Ghi lý do chuyển nhánh hoặc đổi tên"></label>':''}`,c?'Lưu & cập nhật mã':'Đăng ký nội dung'),async v=>{await transact(x=>c?editContent(x,c.id,v):createContent(x,v));await refresh();close();toast(c?'Đã cập nhật nhánh. Mã cũ vẫn tra cứu được.':'Đã đăng ký nội dung và cấp KKKK.');});updateCatGuidance()}
function updateCatGuidance(){const select=dialog.querySelector('[name=categoryId]'),box=$('#cat-guidance');if(!select||!box)return;const c=s.categories.find(x=>x.id===select.value);box.innerHTML=c?`<div><strong>${h(c.code)} · ${h(c.name)}</strong><p>${h(c.include)}</p><small>Loại trừ: ${h(c.exclude||'Chưa bổ sung')}</small></div>`:''}
function categoryDialog(id){const c=s.categories.find(x=>x.id===id);showDialog(c?'Chỉnh sửa CAT':'Thêm nhóm chủ đề',modalForm(`${c?'<div class="notice">Nếu đổi mã CAT, mã lớp hiện hành sẽ đổi theo. Mã cũ trở thành mã tra cứu thay thế; ID lớp không đổi.</div>':''}<div class="form-grid"><label>Mã CAT<input name="code" value="${h(c?.code||'')}" pattern="[A-Za-z][A-Za-z0-9]{1,7}" maxlength="8" required placeholder="Ví dụ: ESG"></label><label>Tên nhóm<input name="name" value="${h(c?.name||'')}" minlength="4" maxlength="100" required placeholder="Tên nhóm chủ đề"></label></div>${c?'<label>Lý do thay đổi<input name="reason" minlength="5" required></label>':'<label>Nội dung bao gồm<textarea name="include" minlength="8" maxlength="500" required placeholder="Nhóm này dùng cho những nội dung nào?"></textarea></label><label>Ranh giới / loại trừ<textarea name="exclude" maxlength="500" placeholder="Những nội dung dễ nhầm nên thuộc nhóm nào khác?"></textarea></label>'}`,c?'Lưu thay đổi':'Thêm & kích hoạt'),async v=>{await transact(x=>c?renameCategory(x,c.id,v):addCategory(x,v));await refresh();close();toast(c?'Đã cập nhật CAT và mã liên quan.':'CAT mới đã có trong danh sách đăng ký nội dung.');})}
function detail(id){const r=s.classes.find(r=>r.id===id),c=s.contents.find(c=>c.id===r.contentId);showDialog('Chi tiết lớp học',`<div class="result-check">${ico('check')}</div><h3>${h(c.title)}</h3><div class="result-code">${h(r.code)}</div><div class="detail-grid"><div><small>ĐƠN VỊ / NHÓM</small><strong>${h(c.owner)} / ${h(categoryFor(s,c).code)}</strong></div><div><small>NGÀY MỞ / HÌNH THỨC</small><strong>${h(r.date)} · ${h(modes[r.mode])}</strong></div><div><small>NỘI DUNG / SỐ ĐĂNG KÝ</small><strong>${pad(c.number,4)} / ${pad(r.run,3)}</strong></div><div><small>TRẠNG THÁI</small><strong>${r.status==='active'?'Đã cấp mã':'Đã hủy · giữ số'}</strong></div></div><label>ID lớp bất biến<code class="id-text">${r.id}</code></label><label>Mã cũ / alias<div class="aliases">${r.aliases.map(a=>`<code>${h(a)}</code>`).join('')||'<span class="muted">Chưa có thay đổi mã.</span>'}</div></label><div class="modal-footer">${btn('Sao chép mã','copy','secondary',r.code)}${r.status==='active'?btn('Hủy lớp','cancel','ghost danger',r.id):''}${btn('Đóng','close','primary')}</div>`)}
function help(){showDialog('Kịch bản trình bày nội bộ',`<ol class="demo-steps"><li><strong>Mở một lớp mới</strong><p>Chọn nội dung, hình thức, ngày. Quan sát mã xem trước và bấm cấp mã.</p></li><li><strong>Thử cấp mã đồng thời</strong><p>Từ Tổng quan, chạy hai yêu cầu. Gửi lại yêu cầu đầu không tạo mã mới.</p></li><li><strong>Thêm một CAT</strong><p>Tạo CAT ESG, đăng ký nội dung trong nhóm mới, rồi mở lớp.</p></li><li><strong>Thay đổi và tra cứu</strong><p>Đổi mã CAT hoặc chuyển nhánh nội dung. Dùng mã cũ tìm lại lớp trong Sổ mã.</p></li></ol><div class="notice warning">Dữ liệu mẫu được tạo để demo. Vai trò chỉ là mô phỏng, không phải đăng nhập hay phân quyền thật. Dữ liệu lưu trong IndexedDB của trình duyệt này; thiết bị hoặc trình duyệt khác có sổ riêng.</div><p>Các tab cùng địa chỉ dùng chung sổ và giao dịch ghi. GitHub Pages chỉ phục vụ giao diện tĩnh, chưa có máy chủ cấp mã cho toàn tập đoàn.</p><div class="modal-footer">${btn('Xuất bản sao JSON','export-json','secondary')}${btn('Đặt lại demo','reset','ghost danger')}${btn('Bắt đầu demo','close','primary')}</div>`)}
async function simulate(){const c=s.contents.find(x=>categoryFor(s,x).active);if(!c)return toast('Cần có nội dung thuộc CAT đang hoạt động.');const id=uid(),input={contentId:c.id,mode:'OF',date:'2026-11-20',label:'Mô phỏng cấp đồng thời'};const results=await Promise.all([transact(x=>issue(x,{...input,requestId:id})),transact(x=>issue(x,{...input,requestId:uid()}))]);const retry=await transact(x=>issue(x,{...input,requestId:id}));await refresh();showDialog('Hai yêu cầu đã được xử lý',`<p>Cùng nội dung <strong>${h(c.title)}</strong>, cùng năm 2026. Hai giao dịch được ghi vào sổ trình duyệt.</p><div class="simulation-results">${results.map((r,i)=>`<div><span class="avatar">${i?'B':'A'}</span><div><small>YÊU CẦU ${i?'B':'A'}</small><code>${h(r.record.code)}</code></div>${pill('Đã cấp','soft')}</div>`).join('')}<div><span class="avatar alt">↻</span><div><small>GỬI LẠI YÊU CẦU A</small><code>${h(retry.record.code)}</code></div>${pill('Giữ mã cũ','soft')}</div></div><div class="notice">Chỉ thêm 2 lớp. Yêu cầu gửi lại không tạo lớp thứ ba. Phạm vi thử: cùng trình duyệt và cùng địa chỉ website.</div><div class="modal-footer">${btn('Xem sổ mã','go-registry','primary')}${btn('Đóng','close','ghost')}</div>`)}
function download(name,text,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function refresh(){s=await read();render()}
function navigate(v){location.hash=v}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{
 if(['new-cat','edit-cat','toggle-cat','edit-content'].includes(a)&&role!=='admin')return toast('Chuyển sang vai trò quản trị mô phỏng để dùng chức năng này.');
 if(a==='navigate')navigate(id);else if(a==='close')close();else if(a==='help')help();else if(a==='new-content')contentDialog();else if(a==='edit-content')contentDialog(id);else if(a==='new-cat')categoryDialog();else if(a==='edit-cat')categoryDialog(id);else if(a==='detail')detail(id);
 else if(a==='open-content'){navigate('issue');setTimeout(()=>{const f=$('#issue-form');if(f){f.elements.contentId.value=id;updatePreview()}},0)}
 else if(a==='toggle-cat'){const c=s.categories.find(c=>c.id===id);showDialog(c.active?'Ngừng sử dụng CAT?':'Kích hoạt lại CAT?',`<p><strong>${h(c.code)} · ${h(c.name)}</strong></p><p>${c.active?'Nhóm sẽ không nhận nội dung hay lớp mới. Các lớp và mã đã có vẫn giữ nguyên.':'Nhóm sẽ xuất hiện lại trong lựa chọn đăng ký nội dung.'}</p>${modalForm('',c.active?'Xác nhận ngừng':'Kích hoạt')}`,async()=>{await transact(x=>setCategoryActive(x,id,!c.active));await refresh();close();toast('Đã cập nhật trạng thái CAT.')})}
 else if(a==='simulation'){b.disabled=true;await simulate()}
 else if(a==='copy'){try{await navigator.clipboard.writeText(id);toast('Đã sao chép mã.')}catch{toast('Không thể dùng clipboard. Bạn có thể chọn và sao chép mã hiển thị.')}}
 else if(a==='cancel'){showDialog('Hủy lớp và giữ mã?',`<p>Lớp chuyển sang trạng thái hủy. Số đã cấp không được tái sử dụng.</p>${modalForm('','Xác nhận hủy')}`,async()=>{await transact(x=>cancelClass(x,id));await refresh();close();toast('Đã hủy lớp và giữ lại mã.')})}
 else if(a==='go-registry'){close();navigate('registry')}
 else if(a==='export-json')download('classcode-demo-backup.json',JSON.stringify(s,null,2),'application/json');
 else if(a==='export-csv'){const rows=[['ID lớp','Namecode','Mã cũ','Tên nội dung','OWN','CAT','KKKK','HT','Năm','DDD','Ngày mở','Nhãn đợt','Trạng thái'],...s.classes.map(r=>{const c=s.contents.find(c=>c.id===r.contentId);return [r.id,r.code,r.aliases.join('; '),c.title,c.owner,categoryFor(s,c).code,pad(c.number,4),r.mode,r.year,pad(r.run,3),r.date,r.label,r.status]})];download('classcode-so-ma.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Đã xuất sổ mã CSV.')}
 else if(a==='reset'){showDialog('Đặt lại dữ liệu demo?',`<p>Xóa các thao tác đã thử trên trình duyệt này và khôi phục dữ liệu minh họa. Xuất JSON trước nếu cần giữ lại kết quả.</p>${modalForm('','Đặt lại demo')}`,async()=>{await reset();await refresh();close();toast('Đã khôi phục dữ liệu minh họa.')})}
 else if(a==='rules')showDialog('Quy tắc namecode',`<div class="result-code">OWN_CAT_KKKK_HT_YYYY_DDD</div><div class="rules-list">${[['OWN','Đơn vị chịu trách nhiệm sở hữu nội dung.'],['CAT','Một cấp nhóm chủ đề từ danh mục quản trị.'],['KKKK','Số nội dung duy nhất toàn sổ, không đặt lại theo năm.'],['HT','OF trực tiếp · ON trực tuyến đồng bộ · EL tự học · BL kết hợp.'],['YYYY','Năm mở lớp. Lớp tự học liên tục không tự đổi mã khi sang năm.'],['DDD','Số đăng ký theo nội dung + năm, xuyên hình thức; bắt đầu 001.']].map(([k,v])=>`<div><code>${k}</code><p>${v}</p></div>`).join('')}</div><div class="modal-footer">${btn('Đã hiểu','close','primary')}</div>`);
 }catch(err){toast(err.message)}finally{b.disabled=false}});
document.addEventListener('submit',async e=>{if(!['issue-form','modal-form'].includes(e.target.id))return;e.preventDefault();const f=e.target,b=f.querySelector('[type=submit]'),error=f.id==='issue-form'?$('#issue-error'):$('#modal-error');b.disabled=true;error.textContent='';try{const v=Object.fromEntries(new FormData(f));if(f.id==='modal-form'){await modalAction(v)}else{const result=await transact(x=>{const matches=x.classes.filter(r=>r.contentId===v.contentId&&r.mode===v.mode&&r.date===v.date&&r.status==='active');if(matches.length&&!v.distinct&&!Object.hasOwn(x.requests,requestId))throw new Error('Có lớp cùng nội dung, hình thức và ngày. Kiểm tra và xác nhận lần mở khác trước khi cấp.');return issue(x,{...v,requestId})});lastIssue=result.record.id;requestId=uid();await refresh();detail(lastIssue);toast('Đã cấp mã và lưu lớp.')}}catch(err){error.textContent=err.message}finally{b.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#table-results').innerHTML=({contents:contentRows,cats:catRows,registry:registryRows}[view])()}if(e.target.closest('#issue-form')&&e.target.name!=='distinct'&&e.target.name!=='label')updatePreview()});
document.addEventListener('change',e=>{if(e.target.id==='role'){role=e.target.value;render()}if(e.target.id==='owner-filter'){ownerFilter=e.target.value;$('#table-results').innerHTML=view==='registry'?registryRows():contentRows()}if(e.target.id==='mode-filter'){modeFilter=e.target.value;$('#table-results').innerHTML=registryRows()}if(e.target.id==='cat-filter'){categoryFilter=e.target.value;$('#table-results').innerHTML=catRows()}if(e.target.name==='categoryId')updateCatGuidance();if(e.target.closest('#issue-form')&&e.target.name!=='distinct')updatePreview()});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);view=['home','issue','contents','cats','registry'].includes(next)?next:'home';search='';ownerFilter='';modeFilter='';requestId=uid();render();window.scrollTo(0,0)});
onUpdate(async()=>{s=await read();if(view==='issue'){toast('Sổ dữ liệu đã thay đổi ở tab khác. Mã sẽ được kiểm tra lại khi cấp.');updatePreview()}else render()});
try{await transact(()=>null);s=await read();view=['home','issue','contents','cats','registry'].includes(location.hash.slice(1))?location.hash.slice(1):'home';render()}catch(err){$('#app').innerHTML=`<div class="startup-error"><h1>Chưa thể mở sổ dữ liệu</h1><p>Prototype cần trình duyệt cho phép IndexedDB. Thử cửa sổ thông thường hoặc cho phép lưu dữ liệu của website.</p><p>${h(err.message)}</p></div>`}
